-- Agent Hub 2.0 (task 09): trace steps and agent memory.
-- RLS workspace-member blocks are generated by module-registry from the manifest.

CREATE TABLE "agent_hub_trace_steps" (
  "id" TEXT NOT NULL,
  "workspaceId" TEXT NOT NULL,
  "executionId" TEXT NOT NULL,
  "stepId" TEXT NOT NULL,
  "parentStepId" TEXT,
  "type" TEXT NOT NULL,
  "name" TEXT,
  "agentId" TEXT,
  "actorId" TEXT NOT NULL,
  "payload" JSONB NOT NULL DEFAULT '{}',
  "durationMs" INTEGER,
  "error" TEXT,
  "attempt" INTEGER NOT NULL DEFAULT 0,
  "at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT "agent_hub_trace_steps_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "agent_memory_records" (
  "id" TEXT NOT NULL,
  "workspaceId" TEXT NOT NULL,
  "scope" TEXT NOT NULL,
  "scopeId" TEXT,
  "key" TEXT NOT NULL,
  "value" JSONB NOT NULL,
  "source" TEXT NOT NULL,
  "agentId" TEXT,
  "userId" TEXT,
  "provenanceEventId" TEXT,
  "validity" TEXT NOT NULL DEFAULT 'valid',
  "supersededById" TEXT,
  "createdById" TEXT NOT NULL,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "agent_memory_records_pkey" PRIMARY KEY ("id")
);

CREATE TABLE "agent_hub_policies" (
  "id" TEXT NOT NULL,
  "workspaceId" TEXT NOT NULL,
  "maxDelegationDepth" INTEGER NOT NULL DEFAULT 3,
  "updatedById" TEXT,
  "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
  "updatedAt" TIMESTAMP(3) NOT NULL,
  CONSTRAINT "agent_hub_policies_pkey" PRIMARY KEY ("id")
);

CREATE UNIQUE INDEX "agent_hub_trace_steps_executionId_stepId_key" ON "agent_hub_trace_steps"("executionId", "stepId");
CREATE INDEX "agent_hub_trace_steps_workspaceId_executionId_at_idx" ON "agent_hub_trace_steps"("workspaceId", "executionId", "at");
CREATE INDEX "agent_hub_trace_steps_workspaceId_agentId_idx" ON "agent_hub_trace_steps"("workspaceId", "agentId");

CREATE INDEX "agent_memory_records_workspaceId_scope_scopeId_key_idx" ON "agent_memory_records"("workspaceId", "scope", "scopeId", "key");
CREATE INDEX "agent_memory_records_workspaceId_key_idx" ON "agent_memory_records"("workspaceId", "key");
CREATE INDEX "agent_memory_records_workspaceId_validity_idx" ON "agent_memory_records"("workspaceId", "validity");
-- Exactly one active value per key: a rewrite supersedes, it never overwrites history.
CREATE UNIQUE INDEX "agent_memory_records_active_key"
  ON "agent_memory_records"("workspaceId", "scope", COALESCE("scopeId", ''), "key")
  WHERE "validity" = 'valid';

CREATE UNIQUE INDEX "agent_hub_policies_workspaceId_key" ON "agent_hub_policies"("workspaceId");

ALTER TABLE "agent_hub_trace_steps" ADD CONSTRAINT "agent_hub_trace_steps_workspaceId_fkey"
  FOREIGN KEY ("workspaceId") REFERENCES "workspaces"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "agent_hub_trace_steps" ADD CONSTRAINT "agent_hub_trace_steps_executionId_fkey"
  FOREIGN KEY ("executionId") REFERENCES "agent_hub_executions"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "agent_memory_records" ADD CONSTRAINT "agent_memory_records_workspaceId_fkey"
  FOREIGN KEY ("workspaceId") REFERENCES "workspaces"("id") ON DELETE CASCADE ON UPDATE CASCADE;
ALTER TABLE "agent_hub_policies" ADD CONSTRAINT "agent_hub_policies_workspaceId_fkey"
  FOREIGN KEY ("workspaceId") REFERENCES "workspaces"("id") ON DELETE CASCADE ON UPDATE CASCADE;
